:root {
  --bg: #0f1115;
  --panel: #171a21;
  --card: #1f232c;
  --border: #2a2f3a;
  --text: #e6e8ee;
  --muted: #9097a5;
  --accent: #8b7cf6;
}
* { box-sizing: border-box; }
body { margin: 0; font-family: system-ui, -apple-system, "Segoe UI", sans-serif; background: var(--bg); color: var(--text); }
header { padding: 16px 24px; background: var(--panel); border-bottom: 1px solid var(--border); }
h1 { margin: 0 0 12px; font-size: 1.4rem; }
form { display: flex; gap: 8px; flex-wrap: wrap; }
input, select, button { font: inherit; padding: 8px 10px; }
input, select { background: var(--card); color: var(--text); border: 1px solid var(--border); border-radius: 8px; color-scheme: dark; }
input { flex: 1; min-width: 200px; }
input:focus, select:focus, button:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
button { background: var(--accent); color: #0f1115; font-weight: 600; border: 0; border-radius: 8px; cursor: pointer; }
button:hover { filter: brightness(1.1); }
#error { color: #ff7b80; margin: 8px 0 0; min-height: 1em; }
#board { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; padding: 24px; align-items: start; }
.column { background: var(--panel); border: 1px solid var(--border); border-radius: 16px; padding: 14px; min-height: 120px; min-width: 0; }
.column h2 { display: flex; align-items: center; gap: 8px; margin: 0 0 12px; font-size: 1rem; }
.count { background: var(--accent); color: #0f1115; border-radius: 999px; padding: 1px 9px; font-size: .75rem; font-weight: 700; }
.card { background: var(--card); border: 1px solid var(--border); border-radius: 10px; padding: 10px 12px; margin-bottom: 8px; box-shadow: 0 1px 3px rgba(0,0,0,.4); overflow-wrap: anywhere; display: flex; justify-content: space-between; align-items: center; gap: 8px; cursor: grab; }
.card:hover { border-color: var(--accent); }
.card .delete { border: none; background: none; cursor: pointer; font-size: 1.2em; color: var(--muted); padding: 4px 8px; }
.card .delete:hover { color: #ff6369; filter: none; }
.card.overdue { border: 2px solid #e5484d; }
.card.due-today { border: 2px solid #f5a524; }
.due { display: block; margin-top: 4px; font-size: .75rem; color: var(--muted); }
.column.over { outline: 2px dashed var(--accent); outline-offset: -2px; }
.pill { display: block; width: fit-content; margin-top: 4px; padding: 1px 8px; border-radius: 999px; color: #fff; font-size: .75rem; font-weight: 600; }
#filter-bar { display: flex; gap: 6px; margin-top: 10px; flex-wrap: wrap; }
#filter-bar .filter { background: transparent; color: var(--text); border: 2px solid var(--c, var(--accent)); border-radius: 999px; padding: 3px 12px; font-weight: 500; }
#filter-bar .filter.active { background: var(--c, var(--accent)); color: #fff; }
@media (max-width: 900px) { #board { grid-template-columns: 1fr; padding: 12px; } }
@media (max-width: 700px) {
  header { padding: 12px; }
  form > * { flex: 1 1 100%; }
  input, select, button { min-height: 44px; }
}

